CREATE TABLE IF NOT EXISTS users(id SERIAL PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(160) UNIQUE NOT NULL,role VARCHAR(30) NOT NULL CHECK(role IN('admin','agent','employee')),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS tickets(id SERIAL PRIMARY KEY,ticket_number VARCHAR(20) UNIQUE,title VARCHAR(180) NOT NULL,description TEXT NOT NULL,priority VARCHAR(20) NOT NULL CHECK(priority IN('LOW','MEDIUM','HIGH','CRITICAL')),status VARCHAR(30) NOT NULL DEFAULT 'NEW' CHECK(status IN('NEW','ASSIGNED','IN_PROGRESS','RESOLVED','CLOSED')),created_by INT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS comments(id SERIAL PRIMARY KEY,ticket_id INT NOT NULL REFERENCES tickets(id) ON DELETE CASCADE,comment TEXT NOT NULL,author VARCHAR(120) NOT NULL DEFAULT 'Admin',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_tickets_status ON tickets(status); CREATE INDEX IF NOT EXISTS idx_tickets_priority ON tickets(priority); CREATE INDEX IF NOT EXISTS idx_tickets_created_at ON tickets(created_at DESC); CREATE INDEX IF NOT EXISTS idx_comments_ticket ON comments(ticket_id);
